      navHelp: "Go to help",
      sectionFaq: "FAQ",
      sectionWhatsNext: "What’s next?",
      whatsNextSubtitle: "Move into day-to-day work in the panel.",
      qs1Title: "Complete business details",
      qs1Desc: "Add your business name, contact and booking page address.",
      qs1Where: "Settings → business details → Save changes",
      qs2Title: "Add services",
      qs2Desc: "Add services the client chooses when booking. A service can be active or inactive.",
